UPDATE content_items SET synopsis = 'Un grupo de jovenes pilotos descubre una ciudad suspendida sobre un oceano de nubes y una senal que podria cambiar el equilibrio de su mundo.', origin = 'Japon', status = 'En emision' WHERE id = 'anime-skybound-echo';
UPDATE content_items SET synopsis = 'En una megaciudad iluminada por neon, un antiguo guerrero protege a una hacker que posee datos capaces de derribar a las corporaciones dominantes.', origin = 'Japon', status = 'Finalizado' WHERE id = 'anime-neon-ronin';
UPDATE content_items SET synopsis = 'Una estudiante llega a una academia nocturna donde cada club guarda un secreto y la luna parece alterar los recuerdos de quienes la observan.', origin = 'Japon', status = 'En emision' WHERE id = 'anime-moonlit-academy';
UPDATE content_items SET synopsis = 'Corredores de distintas regiones compiten en un circuito extremo donde tecnologia y criaturas legendarias definen cada carrera.', origin = 'Japon', status = 'Finalizado' WHERE id = 'anime-dragon-circuit';
UPDATE content_items SET synopsis = 'Dos amigos intentan reconstruir su relacion mientras un pequeno taller de flores se convierte en refugio para historias que nadie se atreve a contar.', origin = 'Japon', status = 'Finalizado' WHERE id = 'anime-silent-bloom';
UPDATE content_items SET synopsis = 'Un delantero sin equipo recibe una invitacion para una liga donde el futbol se mezcla con tecnicas arcanas y rivalidades de alto riesgo.', origin = 'Japon', status = 'En emision' WHERE id = 'anime-arcane-goal';
UPDATE content_items SET synopsis = 'Una carta entregada con diez anos de retraso reune a dos personas que creian haber cerrado para siempre una etapa de sus vidas.', origin = 'Corea del Sur', status = 'Finalizado' WHERE id = 'kdrama-winter-letter';
UPDATE content_items SET synopsis = 'Una chef nocturna y un productor de radio convierten una cocina casi vacia en el punto de encuentro de un barrio que nunca duerme.', origin = 'Corea del Sur', status = 'Finalizado' WHERE id = 'kdrama-midnight-recipe';
UPDATE content_items SET synopsis = 'Una periodista escucha una frecuencia clandestina que anticipa hechos de la ciudad y termina vinculada a un caso que nadie quiere investigar.', origin = 'Corea del Sur', status = 'En emision' WHERE id = 'kdrama-seoul-frequency';
UPDATE content_items SET synopsis = 'Cinco universitarios enfrentan decisiones sobre amistad, familia y futuro mientras intentan cumplir una lista escrita al inicio del semestre.', origin = 'Corea del Sur', status = 'Finalizado' WHERE id = 'kdrama-twenty-steps';
UPDATE content_items SET synopsis = 'Una disenadora de papeleria y un abogado especializado en divorcios descubren que sus ideas sobre el amor cambian al trabajar en el mismo edificio.', origin = 'Corea del Sur', status = 'Finalizado' WHERE id = 'kdrama-paper-hearts';
UPDATE content_items SET synopsis = 'El ultimo tren de la noche conecta a pasajeros con motivos muy distintos para regresar a casa, hasta que una desaparicion altera la ruta.', origin = 'Corea del Sur', status = 'Finalizado' WHERE id = 'kdrama-last-train-home';
UPDATE content_items SET synopsis = 'Una fiscal vuelve al distrito donde crecio y encuentra una red de favores que conecta crimen organizado, politica local y su propia familia.', origin = 'Estados Unidos', status = 'En emision' WHERE id = 'series-north-district';
UPDATE content_items SET synopsis = 'Dos detectives investigan el mismo asesinato desde realidades distintas y descubren que cada decision en un mundo modifica las pistas del otro.', origin = 'Reino Unido', status = 'Finalizado' WHERE id = 'series-parallel-case';
UPDATE content_items SET synopsis = 'Tras un apagado global, un equipo cientifico recibe mensajes que parecen provenir de personas desaparecidas durante el incidente.', origin = 'Canada', status = 'En emision' WHERE id = 'series-after-signal';
UPDATE content_items SET synopsis = 'Un puerto aislado se convierte en el centro de una investigacion cuando un barco abandonado aparece sin tripulacion ni registro de entrada.', origin = 'Reino Unido', status = 'Finalizado' WHERE id = 'series-deep-harbor';
UPDATE content_items SET synopsis = 'Seis ejecutivos quedan encerrados durante una auditoria interna y deben descubrir quien manipulo las cuentas antes de que llegue la policia.', origin = 'Espana', status = 'Finalizado' WHERE id = 'series-glass-room';
UPDATE content_items SET synopsis = 'Una unidad de respuesta intenta contener ataques coordinados contra la infraestructura de una ciudad mientras el sistema electrico colapsa por sectores.', origin = 'Estados Unidos', status = 'En emision' WHERE id = 'series-blackout-protocol';
UPDATE content_items SET synopsis = 'Una mision de rescate entra en una orbita inestable para recuperar a la unica tripulacion que conoce el origen de una anomalía espacial.', origin = 'Estados Unidos', status = 'Estreno 2026' WHERE id = 'movie-crimson-orbit';
UPDATE content_items SET synopsis = 'Cuatro amigos regresan al pueblo costero donde crecieron y descubren que una vieja grabacion conserva la verdad sobre su ultimo verano juntos.', origin = 'Espana', status = 'Disponible' WHERE id = 'movie-static-summer';
UPDATE content_items SET synopsis = 'La ultima guardiana de un fuego ancestral cruza un reino dividido para impedir que una guerra convierta la leyenda en un arma.', origin = 'Nueva Zelanda', status = 'Estreno 2026' WHERE id = 'movie-last-ember';
UPDATE content_items SET synopsis = 'Una cartografa y un navegante siguen una ruta oceanica borrada de los mapas en busca de una isla que solo aparece durante ciertas mareas.', origin = 'Australia', status = 'Disponible' WHERE id = 'movie-blue-meridian';
UPDATE content_items SET synopsis = 'Una fotografa llega a un valle remoto para documentar un pueblo abandonado y encuentra imagenes tomadas antes de su propia llegada.', origin = 'Canada', status = 'Disponible' WHERE id = 'movie-echo-valley';
UPDATE content_items SET synopsis = 'Un editor de cine recibe material de una produccion cancelada y descubre una escena que parece registrar un crimen real ocurrido anos despues.', origin = 'Argentina', status = 'Estreno 2026' WHERE id = 'movie-final-frame';
